WITH gaps AS (SELECT *, CASE WHEN LAG(paid_at) OVER (PARTITION BY method ORDER BY paid_at, id) IS NULL OR paid_at > LAG(paid_at) OVER (PARTITION BY method ORDER BY paid_at, id) + INTERVAL 90 DAYS THEN 1 ELSE 0 END AS is_new_session FROM payments), islands AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY method ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM gaps) SELECT CASE WHEN amount >= 1770 THEN 'HIGH' ELSE 'LOW' END AS amount_tier, COUNT(CASE WHEN method = 'promptpay' THEN 1 END) AS promptpay_count, COUNT(DISTINCT status) AS distinct_status, SORT_ARRAY(COLLECT_SET(status)) AS status_list, (UNIX_TIMESTAMP(MAX(paid_at)) - UNIX_TIMESTAMP(MIN(paid_at))) / 60 AS span_minutes, PERCENTILE_APPROX(amount, ARRAY(0.25, 0.5, 0.75)) AS amount_quartiles, SIZE(COLLECT_SET(status)) AS num_status FROM islands GROUP BY 1 ORDER BY distinct_status DESC NULLS LAST
